//! Swift (and later Kotlin/Python) bindings of `vpn-client`, generated by
//! UniFFI. The app sees plain records and callbacks; the conversation with
//! the daemon, the keychain and the profile file stay in Rust.
//!
//! Threading: callbacks arrive on a Rust worker thread, never on the main
//! thread; the app hops to its own actor before touching the UI.

// Errors cross the FFI by value; boxing them would not shrink anything.
#![allow(clippy::result_large_err)]

use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, Mutex, OnceLock};

use anyhow::Context as _;
use tokio::sync::oneshot;
use vpn_client::{Daemon, Interaction, ProfileStore, Trust};
use vpn_core::ipc::{Event, SessionInfo, SessionState};
use vpn_core::{CertificateInfo, FailureKind, ProtocolConfig};
use zeroize::Zeroizing;

mod forms;
mod types;

pub use forms::*;
pub use types::*;

uniffi::setup_scaffolding!();

/// Product names, from `vpn_core::brand`, so the app never spells them.
#[derive(uniffi::Record)]
pub struct Brand {
    pub product: String,
    pub id: String,
    pub daemon: String,
    pub cli: String,
    pub launchd_label: String,
    pub version: String,
}

#[uniffi::export]
pub fn brand() -> Brand {
    use vpn_core::brand;
    Brand {
        product: brand::PRODUCT.into(),
        id: brand::ID.into(),
        daemon: brand::DAEMON.into(),
        cli: brand::CLI.into(),
        launchd_label: brand::LAUNCHD_LABEL.into(),
        version: vpn_core::version(),
    }
}

/// Certificates from a file the user chose (PEM, or one DER certificate),
/// as PEM; fails when there is none.
#[uniffi::export]
pub fn certificates_as_pem(data: Vec<u8>) -> Result<String, ClientError> {
    Ok(forms::certificates_as_pem(&data)?)
}

/// The Keychain certificates a profile may authenticate with.
#[uniffi::export]
pub fn keychain_identities() -> Result<Vec<KeychainIdentity>, ClientError> {
    Ok(vpn_client::keychain::identities()?
        .into_iter()
        .map(|i| KeychainIdentity { name: i.name, issuer: i.issuer, not_after: i.not_after, sha256: i.sha256 })
        .collect())
}

/// The subjects of the certificates of a PEM bundle, for display.
/// The WireGuard public key that goes with `private_key` (base64), or
/// None if it is not a key.
#[uniffi::export]
pub fn wireguard_public_key(private_key: String) -> Option<String> {
    let private_key = Zeroizing::new(private_key);
    vpn_client::import::public_key(&private_key)
}

/// A new WireGuard private key (base64).
#[uniffi::export]
pub fn new_wireguard_private_key() -> String {
    vpn_client::import::new_private_key().to_string()
}

/// The file is a WireGuard configuration, not an OpenVPN one (both may
/// end in `.conf`).
#[uniffi::export]
pub fn is_wireguard_config(path: String) -> bool {
    vpn_client::import::is_wireguard(std::path::Path::new(&path))
}

#[uniffi::export]
pub fn certificate_names(pem: String) -> Vec<String> {
    forms::certificate_names(&pem)
}

/// The form with its IPsec proposals written out as text, to edit freely.
#[uniffi::export]
pub fn proposals_as_text(form: ProfileForm) -> Result<ProfileForm, ClientError> {
    let mut form = form;
    if !form.custom_proposals {
        (form.ike_proposals, form.esp_proposals) = form.built_proposals()?;
    }
    form.custom_proposals = true;
    Ok(form)
}

/// The form with its IPsec proposals shown as choices again, if the text
/// can be described that way (`custom_proposals` stays set otherwise).
#[uniffi::export]
pub fn proposals_as_choices(form: ProfileForm) -> ProfileForm {
    let mut form = form;
    form.read_proposals();
    form
}

/// Client name sent to the daemon.
const CLIENT: &str = "app";

fn runtime() -> &'static tokio::runtime::Runtime {
    static RUNTIME: OnceLock<tokio::runtime::Runtime> = OnceLock::new();
    RUNTIME.get_or_init(|| {
        tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .thread_name("vpn-client")
            .enable_all()
            .build()
            .expect("tokio runtime")
    })
}

#[derive(uniffi::Object)]
pub struct Client {
    store: Arc<ProfileStore>,
}

#[uniffi::export(async_runtime = "tokio")]
impl Client {
    /// `config_path`: the profiles file, or the default location.
    #[uniffi::constructor]
    pub fn new(config_path: Option<String>) -> Result<Arc<Self>, ClientError> {
        let store = ProfileStore::open(config_path.map(PathBuf::from))?;
        Ok(Arc::new(Self { store: Arc::new(store) }))
    }

    pub fn profiles_path(&self) -> String {
        self.store.path().display().to_string()
    }

    pub fn profiles(&self) -> Result<Vec<ProfileSummary>, ClientError> {
        Ok(self.store.load()?.iter().map(ProfileSummary::from).collect())
    }

    pub fn remove_profile(&self, id: String) -> Result<(), ClientError> {
        Ok(self.store.remove(&id)?)
    }

    /// The profile `id`, for the editor.
    pub fn profile_form(&self, id: String) -> Result<ProfileForm, ClientError> {
        Ok(ProfileForm::from(&self.store.find(&id)?))
    }

    /// An empty profile of `kind`, with the protocol's defaults.
    pub fn new_profile_form(&self, kind: VpnKind) -> ProfileForm {
        ProfileForm::new(kind)
    }

    /// Saves an edited profile (`original`: its id, `None` for a new one);
    /// returns its id. The name may change freely: the id, and with it the
    /// secrets and the chains, stay.
    pub fn save_profile(&self, original: Option<String>, form: ProfileForm) -> Result<String, ClientError> {
        let base = match &original {
            Some(id) => Some(self.store.find(id)?),
            None => None,
        };
        let mut profile = form.to_profile(base.as_ref())?;
        if base.is_none() {
            profile.id = vpn_core::new_id();
        }
        self.store.save(&profile)?;
        Ok(profile.id)
    }

    /// Files `name` in `folder` (None: the top level) and lists it just
    /// before `before` (None: last).
    pub fn move_profile(&self, id: String, folder: Option<String>, before: Option<String>) -> Result<(), ClientError> {
        let mut profile = self.store.find(&id)?;
        if profile.folder != folder {
            profile.folder = folder;
            self.store.save(&profile)?;
        }
        Ok(self.store.reorder(&id, before.as_deref())?)
    }

    /// Copies profile `id` with its saved secrets as `name` (a number is
    /// added if its folder has it already), listed after it. Secrets that
    /// cannot be copied leave the copy without them, to type in the editor.
    pub fn duplicate_profile(&self, id: String, name: String) -> Result<DuplicatedProfile, ClientError> {
        let original = self.store.find(&id)?;
        let copy = self.store.duplicate(&id, Some(&name))?;
        let secrets_error = vpn_client::secrets::copy(&original, &copy).err().map(|e| format!("{e:#}"));
        Ok(DuplicatedProfile { id: copy.id, secrets_error })
    }

    /// The profile as a `.vpnprofile` file: no secret, key or user name.
    pub fn export_profile(&self, id: String) -> Result<String, ClientError> {
        Ok(vpn_client::vpnprofile::export(&self.store.find(&id)?)?)
    }

    /// Reads a `.vpnprofile` file received from someone else; nothing is
    /// added until `save_profile`.
    pub fn read_vpnprofile(&self, path: String) -> Result<ReceivedProfile, ClientError> {
        let metadata = std::fs::metadata(&path).map_err(anyhow::Error::from)?;
        if metadata.len() > vpn_client::vpnprofile::MAX_SIZE as u64 {
            return Err(anyhow::anyhow!("the file is too large for a VPN profile").into());
        }
        let text = std::fs::read_to_string(&path).map_err(anyhow::Error::from)?;
        let profile = vpn_client::vpnprofile::parse(&text)?;
        let name_taken = self.store.load()?.iter().any(|p| p.name == profile.name && p.folder.is_none());
        Ok(ReceivedProfile { form: ProfileForm::from(&profile), name_taken })
    }

    /// Trusts a new certificate in place of the pinned ones, once the user
    /// confirmed it with their IT department.
    pub fn replace_trusted_certificate(&self, id: String, sha256: String) -> Result<(), ClientError> {
        Ok(self.store.set_trusted_certificates(&id, &[sha256.to_ascii_lowercase()])?)
    }

    /// Reads FortiClient's profiles (macOS); nothing is written.
    pub fn import_forticlient(&self, path: Option<String>) -> Result<Vec<ImportedProfile>, ClientError> {
        let path = path.map(PathBuf::from).unwrap_or_else(|| vpn_client::import::FORTICLIENT_PLIST.into());
        Ok(vpn_client::import::forticlient(&path)?
            .into_iter()
            .map(|i| ImportedProfile {
                name: i.name,
                toml: i.toml,
                notes: i.notes,
                needs_psk: i.needs_psk,
                needs_password: false,
                refused: None,
            })
            .collect())
    }

    /// Reads an OpenVPN configuration (.ovpn, .conf) and the files it
    /// names; nothing is written. The profile is renamed if its name is
    /// taken.
    pub fn import_openvpn(&self, path: String) -> Result<Vec<ImportedProfile>, ClientError> {
        let existing: Vec<String> = self.store.load()?.into_iter().map(|p| p.name).collect();
        let imported = vpn_client::import::openvpn(std::path::Path::new(&path), &existing)?;
        let file: vpn_core::ProfileFile = toml::from_str(&imported.toml).map_err(anyhow::Error::from)?;
        let needs_password =
            file.profiles.iter().any(|p| matches!(&p.protocol, ProtocolConfig::OpenVpn(o) if o.auth_user_pass));
        Ok(vec![ImportedProfile {
            name: imported.name,
            toml: imported.toml,
            notes: imported.notes,
            needs_psk: false,
            needs_password,
            refused: None,
        }])
    }

    /// Viscosity's connections (its library when `path` is None, or an
    /// exported `.visc` folder); those that cannot be imported say why.
    pub fn import_viscosity(&self, path: Option<String>) -> Result<Vec<ImportedProfile>, ClientError> {
        let existing: Vec<String> = self.store.load()?.into_iter().map(|p| p.name).collect();
        let found = vpn_client::import::viscosity(path.as_deref().map(std::path::Path::new), &existing)?;
        Ok(found.into_iter().map(ImportedProfile::from).collect())
    }

    /// The VPNs of macOS's System Settings (`path`: another network
    /// configuration file, for tests); those that cannot be imported say why.
    pub fn import_macos(&self, path: Option<String>) -> Result<Vec<ImportedProfile>, ClientError> {
        let existing: Vec<String> = self.store.load()?.into_iter().map(|p| p.name).collect();
        let found = vpn_client::import::macos_vpns(path.as_deref().map(std::path::Path::new), &existing)?;
        Ok(found.into_iter().map(ImportedProfile::from).collect())
    }

    /// What adding the WireGuard configuration at `path` would give; its
    /// keys stay out of it.
    pub fn import_wireguard(&self, path: String) -> Result<ImportedProfile, ClientError> {
        let existing: Vec<String> = self.store.load()?.into_iter().map(|p| p.name).collect();
        let import = vpn_client::import::wireguard(std::path::Path::new(&path), &existing)?;
        let i = import.imported;
        Ok(ImportedProfile {
            name: i.name,
            toml: i.toml,
            notes: i.notes,
            needs_psk: false,
            needs_password: false,
            refused: None,
        })
    }

    /// Adds the WireGuard configuration at `path`, its keys stored in the
    /// Keychain (they never reach the app); returns the new profile's id.
    pub fn add_wireguard(&self, path: String) -> Result<String, ClientError> {
        let existing: Vec<String> = self.store.load()?.into_iter().map(|p| p.name).collect();
        let import = vpn_client::import::wireguard(std::path::Path::new(&path), &existing)?;
        let id = self.store.append(&import.imported.toml)?.into_iter().next().context("nothing added")?;
        let profile = self.store.find(&id)?;
        let stored =
            vpn_client::secrets::set(&profile, "private_key", &import.private_key).and_then(|()| {
                match &import.preshared_key {
                    Some(psk) => vpn_client::secrets::set(&profile, "psk", psk),
                    None => Ok(()),
                }
            });
        if let Err(e) = stored {
            // A profile without its key could not connect.
            let _ = self.store.remove(&id);
            return Err(e.context("cannot store the keys in the Keychain").into());
        }
        Ok(id)
    }

    /// Adds profiles given as TOML (an import's `toml`); returns their ids.
    pub fn add_profiles(&self, toml: String) -> Result<Vec<String>, ClientError> {
        Ok(self.store.append(&toml)?)
    }

    pub fn set_secret(&self, id: String, key: String, value: String) -> Result<(), ClientError> {
        let value = Zeroizing::new(value);
        Ok(vpn_client::secrets::set(&self.store.find(&id)?, &key, &value)?)
    }

    /// Whether a secret is stored (its value is not read out). It queries
    /// the Keychain: call it off the main thread.
    pub fn has_secret(&self, id: String, key: String) -> bool {
        self.store.find(&id).ok().is_some_and(|p| vpn_client::secrets::exists(&p, &key).unwrap_or(false))
    }

    /// Returns whether a secret was stored; false for a profile gone.
    pub fn delete_secret(&self, id: String, key: String) -> Result<bool, ClientError> {
        match self.store.find(&id) {
            Ok(profile) => Ok(vpn_client::secrets::delete(&profile, &key)?),
            Err(_) => Ok(false),
        }
    }

    /// Checks that the service answers and speaks our protocol.
    pub async fn service_info(&self) -> Result<ServiceInfo, ClientError> {
        Ok(on_runtime(async {
            let daemon = Daemon::open(CLIENT).await?;
            let version = daemon.version().to_owned();
            let sessions = daemon.status().await?.len() as u32;
            Ok(ServiceInfo { version, protocol: vpn_core::ipc::PROTOCOL_VERSION, sessions })
        })
        .await?)
    }

    /// The diagnostic report (no secret; servers, accounts, domains and
    /// addresses replaced). `client`: who asks, "Omnitun 0.1.0".
    pub async fn diagnostic_report(&self, client: String) -> String {
        let store = self.store.clone();
        on_runtime(async move { anyhow::Ok(vpn_client::diagnostic::report(&store, &client).await) })
            .await
            .unwrap_or_else(|e| format!("no report: {e}"))
    }

    pub async fn sessions(&self) -> Result<Vec<Session>, ClientError> {
        let sessions = on_runtime(async { Daemon::open(CLIENT).await?.status().await }).await?;
        Ok(sessions.into_iter().map(Session::from).collect())
    }

    /// `id`: the session's profile id.
    pub async fn disconnect(&self, id: String) -> Result<(), ClientError> {
        Ok(on_runtime(async move { Daemon::open(CLIENT).await?.disconnect(&id).await }).await?)
    }

    /// Closes every session and restarts the service.
    pub async fn shutdown(&self) -> Result<(), ClientError> {
        Ok(on_runtime(async { Daemon::open(CLIENT).await?.shutdown().await }).await?)
    }

    /// Starts connecting `profile`. Prompts go to `delegate`, which answers
    /// through the returned `Connection`; `finished` is called once.
    /// `direct`: without the VPNs the profile is chained through; `split`:
    /// only the profile's split-mode networks go through the VPN.
    pub fn connect(
        &self,
        id: String,
        direct: bool,
        split: bool,
        delegate: Arc<dyn ConnectionDelegate>,
    ) -> Arc<Connection> {
        let connection = Arc::new(Connection::default());
        let bridge = Bridge { connection: connection.clone(), delegate: delegate.clone() };
        let store = self.store.clone();
        let task = runtime().spawn(async move {
            let result = async {
                let profile = store.find(&id)?;
                // The app outlives the connection: its signing tasks, once
                // detached, keep signing for the session.
                vpn_client::connect_with(profile, &store, CLIENT, &bridge, vpn_client::ConnectOptions { direct, split })
                    .await
                    .map(drop)
            }
            .await;
            delegate.finished(result.err().map(ClientError::from));
        });
        *connection.task.lock().unwrap() = Some(task);
        connection
    }

    /// Follows the user's sessions: `observer` gets the full list now and
    /// after every change, until the subscription is cancelled or dropped.
    pub fn watch(&self, observer: Arc<dyn SessionObserver>) -> Arc<Subscription> {
        let task = runtime().spawn(async move {
            let result: anyhow::Result<()> = async {
                let mut daemon = Daemon::open(CLIENT).await?.watch().await?;
                let mut sessions: Vec<SessionInfo> = Vec::new();
                loop {
                    match daemon.next().await? {
                        Event::Status { sessions: all } => sessions = all,
                        Event::State { id, state, detail, failure, retry } => {
                            observer.changed(StateChange {
                                id: id.clone(),
                                state: state.into(),
                                detail: detail.as_deref().map(vpn_client::printable),
                                failure: failure.clone().map(FailureInfo::from),
                                retry: retry.map(Into::into),
                            });
                            // States carry no counters or addresses: take a
                            // fresh snapshot of the session that changed.
                            let fresh = Daemon::open(CLIENT).await?.status().await?;
                            sessions.retain(|s| s.id != id);
                            sessions.extend(fresh.into_iter().filter(|s| s.id == id));
                            if state == SessionState::Disconnected {
                                sessions.retain(|s| s.id != id);
                            }
                            sessions.sort_by(|a, b| a.name.cmp(&b.name));
                        }
                        Event::Error { message, failure } => {
                            return Err(vpn_core::failure(failure.unwrap_or(FailureKind::Other), message));
                        }
                        _ => continue,
                    }
                    observer.sessions(sessions.iter().cloned().map(Session::from).collect());
                }
            }
            .await;
            observer.stopped(result.err().map(ClientError::from));
        });
        Arc::new(Subscription { task })
    }
}

/// Runs a future on the client's runtime, whichever executor awaits it.
async fn on_runtime<T: Send + 'static>(
    future: impl Future<Output = anyhow::Result<T>> + Send + 'static,
) -> anyhow::Result<T> {
    runtime().spawn(future).await?
}

/// Receives what a connection needs from the user.
#[uniffi::export(with_foreign)]
pub trait ConnectionDelegate: Send + Sync {
    /// Answer with `Connection::answer(id, …)`.
    fn prompt(&self, id: u64, prompt: Prompt);
    /// Answer with `Connection::trust(id, …)`.
    fn trust_certificate(&self, id: u64, certificate: Certificate);
    /// Open this login page in the browser (already checked to be on the
    /// profile's server).
    fn open_url(&self, url: String);
    fn notice(&self, notice: Notice);
    /// The daemon took the session over (`None`), or it failed.
    fn finished(&self, error: Option<ClientError>);
}

#[uniffi::export(with_foreign)]
pub trait SessionObserver: Send + Sync {
    fn sessions(&self, sessions: Vec<Session>);
    fn changed(&self, change: StateChange);
    /// The daemon went away or refused; subscribe again later.
    fn stopped(&self, error: Option<ClientError>);
}

enum Reply {
    Answer(Option<Zeroizing<String>>),
    Trust(Trust),
}

#[derive(uniffi::Object, Default)]
pub struct Connection {
    next_id: AtomicU64,
    pending: Mutex<HashMap<u64, oneshot::Sender<Reply>>>,
    task: Mutex<Option<tokio::task::JoinHandle<()>>>,
}

#[uniffi::export]
impl Connection {
    /// `None` cancels the connection.
    pub fn answer(&self, id: u64, value: Option<String>) {
        self.reply(id, Reply::Answer(value.map(Zeroizing::new)));
    }

    pub fn trust(&self, id: u64, decision: TrustDecision) {
        self.reply(id, Reply::Trust(decision.into()));
    }

    /// Stops waiting for the user; the daemon abandons the attempt.
    pub fn cancel(&self) {
        self.pending.lock().unwrap().clear();
        if let Some(task) = self.task.lock().unwrap().take() {
            task.abort();
        }
    }
}

impl Connection {
    fn reply(&self, id: u64, reply: Reply) {
        if let Some(waiting) = self.pending.lock().unwrap().remove(&id) {
            let _ = waiting.send(reply);
        }
    }

    fn wait(&self) -> (u64, oneshot::Receiver<Reply>) {
        let id = self.next_id.fetch_add(1, Ordering::Relaxed);
        let (tx, rx) = oneshot::channel();
        self.pending.lock().unwrap().insert(id, tx);
        (id, rx)
    }
}

#[derive(uniffi::Object)]
pub struct Subscription {
    task: tokio::task::JoinHandle<()>,
}

#[uniffi::export]
impl Subscription {
    pub fn cancel(&self) {
        self.task.abort();
    }
}

impl Drop for Subscription {
    fn drop(&mut self) {
        self.task.abort();
    }
}

/// `Interaction` over the delegate: each question waits for its reply.
struct Bridge {
    connection: Arc<Connection>,
    delegate: Arc<dyn ConnectionDelegate>,
}

#[async_trait::async_trait]
impl Interaction for Bridge {
    async fn ask(&self, prompt: &vpn_core::Prompt) -> anyhow::Result<Option<Zeroizing<String>>> {
        let (id, reply) = self.connection.wait();
        self.delegate.prompt(id, prompt.into());
        match reply.await {
            Ok(Reply::Answer(value)) => Ok(value),
            _ => Ok(None),
        }
    }

    async fn trust(&self, certificate: &CertificateInfo) -> anyhow::Result<Trust> {
        let (id, reply) = self.connection.wait();
        self.delegate.trust_certificate(id, certificate.into());
        match reply.await {
            Ok(Reply::Trust(decision)) => Ok(decision),
            _ => Ok(Trust::Reject),
        }
    }

    fn open_url(&self, url: &str) {
        self.delegate.open_url(url.to_owned());
    }

    fn notice(&self, notice: vpn_client::Notice) {
        self.delegate.notice(notice.into());
    }
}

impl From<&vpn_core::Profile> for ProfileSummary {
    fn from(p: &vpn_core::Profile) -> Self {
        let (host, port) = p.protocol.endpoint();
        let (username, auth) = match &p.protocol {
            ProtocolConfig::FortiSsl(s) => (
                s.username.clone(),
                match s.auth {
                    vpn_core::FortiSslAuth::Password => AuthMethod::Password,
                    vpn_core::FortiSslAuth::Saml { .. } => AuthMethod::Saml,
                },
            ),
            ProtocolConfig::Ipsec(i) => (i.username.clone(), AuthMethod::PreSharedKey),
            ProtocolConfig::L2tp(l) => (l.username.clone(), AuthMethod::PreSharedKey),
            ProtocolConfig::WireGuard(_) => (None, AuthMethod::Key),
            ProtocolConfig::OpenVpn(o) => {
                (o.username.clone(), if o.auth_user_pass { AuthMethod::Password } else { AuthMethod::Certificate })
            }
        };
        Self {
            id: p.id.clone(),
            name: p.name.clone(),
            protocol: p.protocol.name().into(),
            host: host.into(),
            port,
            username,
            auth,
            dns_domains: vpn_core::noted::values(&p.dns_domains),
            description: p.description.clone(),
            save_password: p.save_password,
            via: p.via.clone(),
            folder: p.folder.clone(),
            exclusive: p.exclusive,
            split_routes: p
                .split_routes
                .iter()
                .map(|e| forms::ListEntry { value: e.value.to_string(), note: e.note.clone().unwrap_or_default() })
                .collect(),
        }
    }
}
